/**
 * Homophones for what Meijia misreads, checked by comparing her recordings: she says 和 as ㄏㄜˊ
 * where the lessons read ㄏㄢˋ, and 「從左邊數」 as ㄕㄨˋ (as in 樹) instead of ㄕㄨˇ. 數一數 she
 * reads right.
 */
const spokenFixes: [RegExp, string][] = [
  [/和/g, "漢"],
  [/邊數，/g, "邊鼠，"],
];

/** What Meijia is given to say; the screen still shows the prompt as written. */
export const mathPromptSpeech = (id: string) =>
  spokenFixes.reduce((text, [pattern, fix]) => text.replace(pattern, fix), mathPrompts[id] ?? "");

export { isHan };

/** The selectors that make each character of an instruction show its reading. */
export const mathPromptVariants = (id: string): Record<number, string> =>
  readingVariants(mathPrompts[id] ?? "", mathPromptReadings[id] ?? "");

export const mathPromptId = (question: {
  kind: string;
  target: number;
  parts?: readonly number[];
}) =>
  question.kind === "count"
    ? "count"
    : question.kind === "ways"
      ? `ways-${question.target}`
      : question.parts
        ? `${question.kind}-${question.parts.join("-")}`
        : `draw-${question.target}`;

/** Clips re-recorded after their sentence changed; the query skips a cached old clip. */
const promptVersions: Record<string, number> = { count: 2 };

/** Page-relative, like every public file (see CLAUDE.md). */
export const mathPromptUrl = (id: string) => `math-audio/${id}.m4a?v=${promptVersions[id] ?? 1}`;
